<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import http from'../api/http';import{useAuthStore}from'../stores/auth'
const auth=useAuthStore(),rows=ref<any[]>([]),total=ref(0),doctors=ref<any[]>([]),departments=ref<any[]>([]),loading=ref(false),dialog=ref(false),saving=ref(false);const query=reactive({page:1,page_size:10,department_id:undefined as number|undefined,date_from:'',date_to:''});const form=reactive({doctor_id:undefined as number|undefined,schedule_date:'',start_time:'08:00',end_time:'12:00',slot_minutes:30})
const canManage=computed(()=>auth.user?.role!=='patient')
async function load(){loading.value=true;try{const [s,d,dep]=await Promise.all([http.get('/schedules',{params:query}),http.get('/doctors',{params:{page_size:100,department_id:query.department_id}}),http.get('/departments',{params:{page_size:100}})]);rows.value=s.data.results;total.value=s.data.count;doctors.value=d.data.results;departments.value=dep.data.results}finally{loading.value=false}}
async function save(){if(!form.doctor_id||!form.schedule_date)return ElMessage.warning('请选择医师和日期');saving.value=true;try{await http.post('/schedules',{...form,start_time:`${form.start_time}:00`,end_time:`${form.end_time}:00`});ElMessage.success('排班及号源生成成功');dialog.value=false;load()}finally{saving.value=false}}
function reserve(row:any){sessionStorage.setItem('selected_schedule',JSON.stringify(row));location.href='/appointments'}
onMounted(load)
</script>
<template><div><div class="page-title"><div><h1>{{canManage?'医师排班':'就诊预约'}}</h1><p>{{canManage?'维护医师出诊时间，系统自动拆分预约号源':'按科室和日期查找可预约医师'}}</p></div><el-button v-if="canManage" type="primary" @click="dialog=true">新增排班</el-button></div><el-card><div class="toolbar"><el-select v-model="query.department_id" clearable placeholder="全部科室" @change="query.page=1;load()"><el-option v-for="x in departments" :key="x.id" :label="x.name" :value="x.id"/></el-select><el-date-picker v-model="query.date_from" value-format="YYYY-MM-DD" placeholder="开始日期"/><el-date-picker v-model="query.date_to" value-format="YYYY-MM-DD" placeholder="结束日期"/><el-button @click="query.page=1;load()">查询</el-button></div><el-table v-loading="loading" :data="rows"><el-table-column prop="schedule_date" label="出诊日期"/><el-table-column prop="department_name" label="科室"/><el-table-column prop="doctor_name" label="医师"/><el-table-column prop="doctor_title" label="职称"/><el-table-column label="出诊时间"><template #default="{row}">{{row.start_time.slice(0,5)}}–{{row.end_time.slice(0,5)}}</template></el-table-column><el-table-column prop="available_slots" label="剩余号源"/><el-table-column v-if="!canManage" label="操作"><template #default="{row}"><el-button type="primary" link :disabled="!row.available_slots" @click="reserve(row)">选择号源</el-button></template></el-table-column></el-table><div class="pagination"><span>共 {{total}} 条</span><el-pagination v-model:current-page="query.page" layout="prev,pager,next" :total="total" @current-change="load"/></div></el-card><el-dialog v-model="dialog" title="新增医师排班" width="560px"><el-form label-position="top"><el-form-item label="出诊医师" required><el-select v-model="form.doctor_id" style="width:100%"><el-option v-for="x in doctors" :key="x.id" :label="`${x.full_name} · ${x.department_name}`" :value="x.id"/></el-select></el-form-item><el-form-item label="出诊日期" required><el-date-picker v-model="form.schedule_date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item><el-row :gutter="12"><el-col :span="8"><el-form-item label="开始时间"><el-time-select v-model="form.start_time" start="07:00" step="00:30" end="19:00"/></el-form-item></el-col><el-col :span="8"><el-form-item label="结束时间"><el-time-select v-model="form.end_time" start="07:30" step="00:30" end="20:00"/></el-form-item></el-col><el-col :span="8"><el-form-item label="每号分钟"><el-select v-model="form.slot_minutes"><el-option :value="15"/><el-option :value="30"/><el-option :value="60"/></el-select></el-form-item></el-col></el-row></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">生成排班</el-button></template></el-dialog></div></template>
